using AiPromptHelper.Core;
var passed = 0;
var failed = 0;
void Test(string name, Action action) { try { action(); Console.WriteLine("PASS " + name); passed++; } catch (Exception e) { Console.WriteLine("FAIL " + name + ": " + e.Message); failed++; } }
void Assert(bool value) { if (!value) throw new Exception("条件を満たしません"); }
void Throws(Action action) { try { action(); } catch { return; } throw new Exception("例外が必要です"); }
Template Base() => new() { Id = "test", Name = "テスト", Category = "テスト", Questions = [new() { Id = "a", Label = "質問", Type = "text" }, new() { Id = "b", Label = "分岐", Type = "text", VisibleWhen = new() { QuestionId = "a", Operator = "equals", Value = Json.Element("yes") } }], Prompt = "{{a}} / {{b}}" };
var root = Path.Combine(Path.GetTempPath(), "AiPromptHelper-tests-" + Guid.NewGuid());
Directory.CreateDirectory(root);
try
{
    Test("日本語JSONを直接読み書き",()=>{var t=Base();t.Name="アイデアを出す";t.Prompt="引用符\"と改行\nと文字列\\u30A2";var json=Json.Write(t);Assert(json.Contains("アイデアを出す"));Assert(Json.Read<Template>(json).Prompt==t.Prompt);});
    Test("既存エスケープJSONを内容保持して移行",()=>{var storage=new Storage(Path.Combine(root,"readable"));var t=Base();t.Name="アイデアを出す";var node=System.Text.Json.Nodes.JsonNode.Parse(Json.Write(t))!;node["customProperty"]="保持する\\u30A2";var original=node.ToJsonString();var path=Path.Combine(storage.Root,"templates","test.json");File.WriteAllText(path,original);Assert(storage.LoadTemplates().Count==1);var readable=File.ReadAllText(path);Assert(readable.Contains("アイデアを出す"));Assert(System.Text.Json.Nodes.JsonNode.Parse(readable)!["customProperty"]!.GetValue<string>()=="保持する\\u30A2");Assert(File.ReadAllText(path+".unicode.bak")==original);storage.LoadTemplates();Assert(File.ReadAllText(path)==readable);});
    Test("破損テンプレートは日本語変換でも保持",()=>{var storage=new Storage(Path.Combine(root,"readable-broken"));var path=Path.Combine(storage.Root,"templates","bad.json");var original="{\"name\":\"\\u30A2\"";File.WriteAllText(path,original);Assert(storage.LoadTemplates().Count==0);Assert(File.ReadAllText(path)==original&&!File.Exists(path+".unicode.bak"));});
    Test("既存回答スタイルの日本語変換・未知項目・選択を保持",()=>{
        var storage=new Storage(Path.Combine(root,"readable-styles"));
        var node=System.Text.Json.Nodes.JsonNode.Parse(Json.Write(new AnswerStyleFile()))!;
        node["customProperty"]="元の内容";
        var original=node.ToJsonString();
        var path=Path.Combine(storage.Root,"answer_styles.json");File.WriteAllText(path,original);
        var settings=new Settings();settings.AnswerStyleSelections["length"]=4;
        storage.LoadAnswerStyles(settings);
        var after=File.ReadAllText(path);
        Assert(after.Contains("文章の長さ")&&settings.ResponseStyles[0].SelectedIndex==4);
        Assert(System.Text.Json.JsonElement.DeepEquals(Json.Read<System.Text.Json.JsonElement>(original),Json.Read<System.Text.Json.JsonElement>(after)));
        Assert(File.ReadAllText(path+".unicode.bak")==original);
        storage.LoadAnswerStyles(settings);Assert(File.ReadAllText(path)==after);
    });
    Test("回答スタイル省略は従来どおりON・不正な型を拒否",()=>{Assert(Json.Read<Template>("""{"schemaVersion":1}""").UseAnswerStyle);Assert(Json.Read<Bookmark>("{}").UseAnswerStyle);Throws(()=>Json.Read<Template>("""{"schemaVersion":1,"useAnswerStyle":"false"}"""));});
    Test("回答スタイルOFFは相談と作業指示のみ",()=>{var t=Base();t.UseAnswerStyle=false;t.Prompt="上記の希望に合わせて画像を生成してください。";var text=PromptComposer.Compose(t,new Dictionary<string,string[]>{{"a",["画像の題材"]}},new Settings());Assert(text.StartsWith(PromptComposer.ConsultationHeading));Assert(text.Contains("画像の題材")&&text.Contains(t.Prompt));Assert(!text.Contains(PromptComposer.StyleHeading)&&!text.Contains(PromptComposer.Closing));t.UseAnswerStyle=true;text=PromptComposer.Compose(t,new Dictionary<string,string[]>(),new Settings());Assert(text.StartsWith(PromptComposer.StyleHeading)&&text.EndsWith(PromptComposer.Closing));});
    Test("回答スタイルOFFをテンプレート保存・再読込で保持",()=>{var storage=new Storage(Path.Combine(root,"style-off-template"));var t=Base();t.UseAnswerStyle=false;storage.SaveTemplate(t);Assert(!storage.LoadTemplates()[t.Id].Template.UseAnswerStyle);});
    Test("OFFブックマークは元テンプレートなしでも設定を保持",()=>{var storage=new Storage(Path.Combine(root,"style-off-bookmark"));var vm=new AiPromptHelper.ViewModels.MainViewModel(storage);var t=Base();t.UseAnswerStyle=false;vm.Start(t);vm.Generate();var original=vm.Prompt;vm.SaveBookmark("画像");var vm2=new AiPromptHelper.ViewModels.MainViewModel(storage);vm2.Start(Base());vm2.OpenBookmark(vm2.Bookmarks.Items.Single());Assert(!vm2.UseAnswerStyle&&vm2.Active==null);vm2.RefreshResponseStyle();Assert(vm2.Prompt==original);vm2.SaveBookmark("再保存",vm2.Bookmarks.Items.Single());Assert(!storage.LoadBookmarks().Items.Single().UseAnswerStyle);vm2.Start(Base());Assert(vm2.UseAnswerStyle);});
    Test("必須選択式は自由入力だけで回答可能",()=>{foreach(var type in new[]{"singleSelect","multiSelect"}){var q=new Question{Type=type,Required=true,Options=[new(){Value="a",Label="A"}]};Assert(Engine.AnswerError(q,[Engine.CustomAnswer("どれにも当てはまらない回答")])==null);Assert(Engine.AnswerError(q,[Engine.CustomAnswer(" \n")])!=null);Assert(Engine.AnswerError(q,[Engine.CustomAnswer(new string('x',6001))])!=null);}});
    Test("単一は排他・複数は既存選択と自由入力を併用",()=>{var q=new Question{Type="singleSelect",Options=[new(){Value="a",Label="A"}]};var a=new[]{"a",Engine.CustomAnswer("独自回答")};Assert(Engine.AnswerError(q,a)!=null);q.Type="multiSelect";Assert(Engine.AnswerError(q,a)==null);Assert(Engine.AnswerError(q,[Engine.CustomAnswer("x"),Engine.CustomAnswer("y")])!=null);Assert(Engine.AnswerError(q,["未定義の値"])!=null);});
    Test("自由入力は回答として出力し内部記号や補足表記を出さない",()=>{var t=Base();t.UseAnswerStyle=false;t.Questions[0].Type="singleSelect";t.Questions[0].Options=[new(){Value="yes",Label="はい"}];var a=new Dictionary<string,string[]>{{"a",[Engine.CustomAnswer("希望\n{{b}}")]}};var text=PromptComposer.Compose(t,a,new Settings());Assert(text.Contains("回答：希望\n{{b}}"));Assert(!text.Contains("__custom_answer__")&&!text.Contains("補足："));Assert(Engine.Generate(t,a).StartsWith("希望\n{{b}}"));});
    Test("自由入力は回答済み分岐だけ有効・選択肢とは区別",()=>{var a=new[]{Engine.CustomAnswer("yes")};Assert(!Engine.Evaluate(new(){QuestionId="a",Operator="equals",Value=Json.Element("yes")},_=>a));Assert(!Engine.Evaluate(new(){QuestionId="a",Operator="contains",Value=Json.Element("yes")},_=>a));Assert(Engine.Evaluate(new(){QuestionId="a",Operator="isAnswered"},_=>a));Assert(!Engine.Evaluate(new(){QuestionId="a",Operator="isAnswered"},_=>[Engine.CustomAnswer(" ")]));var t=Base();var answers=new Dictionary<string,string[]>{{"a",a},{"b",[Engine.CustomAnswer("非表示の回答")]}};Assert(!PromptComposer.Compose(t,answers,new Settings()).Contains("非表示の回答"));});
    Test("自由入力を保持・再開始で消去・ブックマーク本文へ保存",()=>{var storage=new Storage(Path.Combine(root,"custom-answers"));var vm=new AiPromptHelper.ViewModels.MainViewModel(storage);vm.Start(Base());vm.Answers["a"]=[Engine.CustomAnswer("追加希望")];vm.Index=1;vm.Index=0;Assert(Engine.CustomText(vm.Answers["a"][0])=="追加希望");vm.Generate();vm.SaveBookmark("自由入力");Assert(storage.LoadBookmarks().Items.Single().PromptText.Contains("回答：追加希望"));vm.Start(Base());Assert(!vm.Answers["a"].Any(Engine.IsCustomAnswer));});
    Test("自由入力の内部接頭辞を選択肢として使用しない",()=>{var t=Base();t.Questions[0].Type="singleSelect";t.Questions[0].Options=[new(){Value=Engine.CustomAnswer("x"),Label="x"}];Assert(Engine.Validate(t).Count>0);});
    Test("保存先をEXE配下dataに統一し旧フォルダーを作成しない",()=>{var app=Path.Combine(root,"location-new","app");var local=Path.Combine(root,"location-new","local");Directory.CreateDirectory(app);var store=AppDataLocation.Open(app,local);Assert(store.Root==Path.Combine(app,"data"));Assert(Directory.Exists(Path.Combine(store.Root,"templates")));Assert(!Directory.Exists(Path.Combine(local,"AiPromptHelper")));});
    Test("旧データを内容保持して一度だけ引き継ぐ",()=>{var app=Path.Combine(root,"location-migrate","app");var local=Path.Combine(root,"location-migrate","local");var old=Path.Combine(local,"AiPromptHelper");Directory.CreateDirectory(Path.Combine(old,"templates"));Directory.CreateDirectory(app);File.WriteAllText(Path.Combine(old,"settings.json"),"broken-original");File.WriteAllText(Path.Combine(old,"bookmarks.json"),"saved-bookmark");File.WriteAllText(Path.Combine(old,"templates","mine.json"),"user-template");var store=AppDataLocation.Open(app,local);Assert(File.ReadAllText(Path.Combine(store.Root,"settings.json"))=="broken-original");Assert(File.ReadAllText(Path.Combine(store.Root,"bookmarks.json"))=="saved-bookmark");Assert(File.ReadAllText(Path.Combine(store.Root,"templates","mine.json"))=="user-template");Assert(File.ReadAllText(Path.Combine(old,"settings.json"))=="broken-original");File.Delete(Path.Combine(store.Root,"templates","mine.json"));AppDataLocation.Open(app,local);Assert(!File.Exists(Path.Combine(store.Root,"templates","mine.json")));});
    Test("新保存先の編集を旧データで上書きしない",()=>{var app=Path.Combine(root,"location-existing","app");var local=Path.Combine(root,"location-existing","local");var old=Path.Combine(local,"AiPromptHelper");Directory.CreateDirectory(old);Directory.CreateDirectory(Path.Combine(app,"data"));File.WriteAllText(Path.Combine(old,"settings.json"),"old");File.WriteAllText(Path.Combine(app,"data","settings.json"),"new");var store=AppDataLocation.Open(app,local);Assert(File.ReadAllText(Path.Combine(store.Root,"settings.json"))=="new");});
    Test("外部回答スタイルを初期配置・明示保存先では旧データを移行しない",()=>{var app=Path.Combine(root,"location-style","app");var local=Path.Combine(root,"location-style","local");var custom=Path.Combine(root,"location-style","explicit");Directory.CreateDirectory(app);var file=new AnswerStyleFile();file.Items[0].Label="利用者の定義";File.WriteAllText(Path.Combine(app,"answer_styles.json"),Json.Write(file));Directory.CreateDirectory(Path.Combine(local,"AiPromptHelper"));File.WriteAllText(Path.Combine(local,"AiPromptHelper","settings.json"),"legacy");var store=AppDataLocation.Open(app,local,custom);Assert(store.Root==Path.GetFullPath(custom));Assert(!File.Exists(Path.Combine(custom,"settings.json")));Assert(store.LoadSettings().ResponseStyles[0].Label=="利用者の定義");});
    Test("正常なテンプレート", () => Assert(Engine.Validate(Base()).Count == 0));
    Test("schemaVersionは必須", () => Throws(() => Json.Read<Template>("{\"id\":\"test\"}")));
    Test("不正な置換記号", () => { var t = Base(); t.Prompt = "{{a"; Assert(Engine.Validate(t).Count > 0); t.Prompt = "{{invalid id}}"; Assert(Engine.Validate(t).Count > 0); });
    Test("既定値の型", () => { var t = Base(); t.Questions[0].Default = Json.Element(new[] { "one", "two" }); Assert(Engine.Validate(t).Count > 0); });
    Test("不正な条件値", () => { var t = Base(); t.Questions[1].VisibleWhen!.Value = Json.Element(new { bad = "value" }); Assert(Engine.Validate(t).Count > 0); });
    Test("null選択肢を除外", () => { var t = Base(); t.Questions[0].Options = null!; Assert(Engine.Validate(t).Count > 0); });
    Test("未知バージョン", () => { var t = Base(); t.SchemaVersion = 2; Assert(Engine.Validate(t).Count > 0); });
    Test("質問ID重複", () => { var t = Base(); t.Questions[1].Id = "a"; Assert(Engine.Validate(t).Count > 0); });
    Test("不明なプレースホルダー", () => { var t = Base(); t.Prompt = "{{missing}}"; Assert(Engine.Validate(t).Count > 0); });
    Test("未定義の条件参照", () => { var t = Base(); t.Questions[1].VisibleWhen!.QuestionId = "missing"; Assert(Engine.Validate(t).Count > 0); });
    Test("循環条件", () => { var t = Base(); t.Questions[0].VisibleWhen = new() { QuestionId = "b", Operator = "isAnswered" }; Assert(Engine.Validate(t).Count > 0); });
    Test("未知の演算子", () => { var t = Base(); t.Questions[1].VisibleWhen!.Operator = "bad"; Assert(Engine.Validate(t).Count > 0); });
    Test("無効範囲", () => { var t = Base(); t.Questions[0].Min = 10; t.Questions[0].Max = 1; Assert(Engine.Validate(t).Count > 0); });
    Test("null質問", () => { var t = Base(); t.Questions = null!; Assert(Engine.Validate(t).Count > 0); });
