        Test("条件演算子 " + op, () => { var c = new Condition { QuestionId = "a", Operator = op, Value = op == "in" ? Json.Element(new[] { "yes", "no" }) : Json.Element(op == "notEquals" ? "no" : op == "contains" ? "es" : "yes") }; Assert(Engine.Evaluate(c, _ => ["yes"])); });
