    Test("HSV基準色と往復変換",()=>{Assert(Appearance.HsvToRgb(0,1,1)==((byte)255,(byte)0,(byte)0));Assert(Appearance.HsvToRgb(120,1,1)==((byte)0,(byte)255,(byte)0));var hsv=Appearance.RgbToHsv(67,142,131);Assert(Appearance.HsvToRgb(hsv.H,hsv.S,hsv.V)==((byte)67,(byte)142,(byte)131));});
    Test("アクセント上の文字コントラストを明暗全域で確保",()=>{for(int r=0;r<=255;r+=17)for(int g=0;g<=255;g+=17)for(int b=0;b<=255;b+=17){double l=Appearance.Luminance((byte)r,(byte)g,(byte)b);var fg=Appearance.ContrastText((byte)r,(byte)g,(byte)b);double ratio=fg=="#000000"?(l+.05)/.05:1.05/(l+.05);Assert(ratio>=4.5);}});
    Test("同梱8件・3〜5問・選択肢3〜5個・最後は任意補足", () => { Assert(templates.Length==8); foreach(var t in templates){Assert(t.Questions.Count is >=3 and <=5);Assert(t.Questions.Last().Id=="extra"&&!t.Questions.Last().Required);foreach(var q in t.Questions.Where(q=>q.Type is "singleSelect" or "multiSelect"))Assert(q.Options.Count is >=3 and <=5);Assert(!t.Prompt.Contains("必要な情報が不足している場合は確認の質問をしてください。"));} });
    Test("6入力型の検証を維持",()=>{foreach(var type in Engine.Types){var t=Base();t.Questions[0].Type=type;t.Questions[0].Options=[new(){Label="選択",Value="x"}];t.Questions[0].Min=0;t.Questions[0].Max=10;t.Questions[0].Step=1;Assert(Engine.Validate(t).Count==0);}});
    Test("回答スタイル初期4項目と指定色",()=>{var s=new Settings();Assert(s.ResponseStyles.Count==4&&s.ResponseStyles.All(x=>x.Values.Count==5));Assert(s.AccentColor=="#438E83");Storage.ValidateSettings(s);});
    Test("旧設定JSONとの互換性",()=>{var s=Json.Read<Settings>("{\"schemaVersion\":1,\"theme\":\"dark\"}");Storage.ValidateSettings(s);Assert(s.Theme=="dark"&&s.ResponseStyles.Count==4);});
    Test("JSONで回答スタイル項目・段階を変更",()=>{var s=new Settings{ResponseStyles=[new(){Id="custom",Label="変更した質問",LowLabel="弱",HighLabel="強",Values=["A","B","C","D","E","F","G"],SelectedIndex=6}]};Storage.ValidateSettings(s);var f=new Storage(Path.Combine(root,"style"));f.SaveSettings(s);var restored=f.LoadSettings();Assert(restored.ResponseStyles[0].Values.Count==7&&restored.ResponseStyles[0].SelectedIndex==6);Assert(PromptComposer.StyleText(restored.ResponseStyles).Contains("変更した質問：G"));});
    Test("不正なスタイル設定は保存拒否",()=>{var s=new Settings();s.ResponseStyles[0].SelectedIndex=99;Throws(()=>Storage.ValidateSettings(s));s.ResponseStyles[0].SelectedIndex=0;s.ResponseStyles[0].Values=[];Throws(()=>Storage.ValidateSettings(s));});
    Test("不正な色は保存拒否",()=>{var s=new Settings{AccentColor="red"};Throws(()=>Storage.ValidateSettings(s));});
    Test("スタイル・相談・質問回答・末尾指示の順序",()=>{var p=PromptComposer.Compose(Base(),new Dictionary<string,string[]>{{"a",["yes"]},{"b",["detail"]}},new());Assert(p.StartsWith("【回答スタイル】"));Assert(p.Contains("【相談内容】\n質問\n回答：yes"));Assert(p.Contains("分岐\n回答：detail"));Assert(p.EndsWith(PromptComposer.Closing));});
    Test("プレビューの本文編集を維持してスタイル即時反映",()=>{var s=new Settings();var p=PromptComposer.Compose(Base(),new Dictionary<string,string[]>{{"a",["yes"]}},s).Replace("回答：yes","回答：手動編集");s.ResponseStyles[0].SelectedIndex=4;var updated=PromptComposer.UpdateStyle(p,s);Assert(updated.Contains("文章の長さ：十分詳しく")&&updated.Contains("回答：手動編集"));Assert(updated.Split("【回答スタイル】").Length==2);Assert(updated.EndsWith(PromptComposer.Closing));});
    Test("旧ブックマークのスタイル変更でも元本文を保全",()=>{var p=PromptComposer.UpdateStyle("旧版の文章",new());Assert(p.EndsWith("旧版の文章"));Assert(p.StartsWith("【回答スタイル】"));});
    Test("スキップは必須でも進めてプロンプトに明記",()=>{var t=Base();t.Questions[0].Required=true;Assert(Engine.AnswerError(t.Questions[0],["__skip__"])==null);var a=new Dictionary<string,string[]>{{"a",["__skip__"]},{"b",["秘密"]}};var p=PromptComposer.Compose(t,a,new());Assert(p.Contains("質問\n回答：スキップ（わからない）")&&!p.Contains("秘密")&&!p.Contains("__skip__"));});
    Test("スキップは回答済み分岐を有効にしない",()=>Assert(!Engine.Evaluate(new(){QuestionId="a",Operator="isAnswered"},_=>["__skip__"])));
    Test("選択値でなく表示ラベルを相談文に使用",()=>{var t=Base();t.Questions[0].Type="singleSelect";t.Questions[0].Options=[new(){Value="internal",Label="表示する回答"}];var p=PromptComposer.Compose(t,new Dictionary<string,string[]>{{"a",["internal"]}},new());Assert(p.Contains("質問\n回答：表示する回答"));});
    Test("旧定型の再質問指示を出力から除去",()=>{var t=Base();t.Prompt="必要な情報が不足している場合は確認の質問をしてください。未回答の項目は推測で埋めないでください。";Assert(!PromptComposer.Compose(t,new Dictionary<string,string[]>(),new()).Contains("必要な情報が不足"));});
    Test("未編集の旧同梱だけ更新",()=>{var s=new Storage(Path.Combine(root,"upgrade"));var old=Base();s.SaveTemplate(old);var revised=Json.Read<Template>(Json.Write(old));revised.Name="新版";s.UpgradeBundled([old],[revised]);Assert(s.LoadTemplates()[old.Id].Template.Name=="新版");});
    Test("利用者編集・削除・破損テンプレートは更新で上書きしない",()=>{var s=new Storage(Path.Combine(root,"upgrade-preserve"));var old=Base();var edited=Json.Read<Template>(Json.Write(old));edited.Name="利用者の編集";var f=s.SaveTemplate(edited);var revised=Json.Read<Template>(Json.Write(old));revised.Name="新版";s.UpgradeBundled([old],[revised]);Assert(s.LoadTemplates()[old.Id].Template.Name=="利用者の編集");File.WriteAllText(f,"broken");s.UpgradeBundled([old],[revised]);Assert(File.ReadAllText(f)=="broken");File.Delete(f);s.UpgradeBundled([old],[revised]);Assert(!File.Exists(f));});
    Test("未知の設定項目を読み込み保存時に除去",()=>{var s=new Storage(Path.Combine(root,"unknown-settings"));Directory.CreateDirectory(s.Root);File.WriteAllText(Path.Combine(s.Root,"settings.json"),"""{"schemaVersion":1,"theme":"dark","accentColor":"#587D9A","fontSizePt":12,"unknownEnabled":true,"unknownMode":"new","unknownAction":"send","unknownMethod":"custom"}""");var v=s.LoadSettings();Assert(v.Theme=="dark"&&v.AccentColor=="#587D9A"&&v.FontSizePt==12);s.SaveSettings(v);var json=File.ReadAllText(Path.Combine(s.Root,"settings.json"));Assert(!json.Contains("unknownEnabled")&&!json.Contains("unknownMode")&&!json.Contains("unknownAction")&&!json.Contains("unknownMethod"));});
    foreach (var t in templates)
        Test("同梱テンプレート生成 " + t.Id, () => { Assert(Engine.Validate(t).Count == 0); var a = t.Questions.ToDictionary(q => q.Id, q => Engine.DefaultAnswer(q)); foreach (var q in t.Questions) { if (a[q.Id].Length == 0) a[q.Id] = q.Type is "singleSelect" or "multiSelect" ? [q.Options[0].Value] : q.Type is "number" or "slider" ? [(q.Min ?? 1).ToString(System.Globalization.CultureInfo.InvariantCulture)] : ["テスト回答"]; Assert(Engine.AnswerError(q, a[q.Id]) == null); } Assert(!string.IsNullOrWhiteSpace(Engine.Generate(t, a))); });
}
finally { Directory.Delete(root, true); }
Console.WriteLine($"結果: {passed} 成功 / {failed} 失敗");
return failed == 0 ? 0 : 1;










